// Basic Non-Template Aliases

typedef unsigned int UI32;
UI32 frame_count = 0;

typedef void (*HandlerFunc)(int);
HandlerFunc callback;

// Modern C++ Aliases (C++11+)
using PosType = long double;
PosType x = 1.0;

using ConfigMap = std::map<std::string, std::string>;
ConfigMap settings;


// Template Aliases (Cannot be done with 'typedef')

template <typename T>
using Matrix = std::vector<std::vector<T>>;

Matrix<float> projection;

template <typename T>
using SmartPtr = std::unique_ptr<T>;

SmartPtr<Resource> handle(new Resource());
